SourceCode.Declaration:
using Microsoft.Dynamics.Application.Instrumentation;
using Microsoft.Dynamics.Commerce.Headquarters.Instrumentation;

public class GUPRetailPricingDataManager
    extends RetailPricingDataManager
    implements Microsoft.Dynamics.Commerce.Runtime.Services.PricingEngine.IPricingDataAccessorGlobalUnifiedPricing
{
    Microsoft.Dynamics.Commerce.Runtime.DataModel.UnifiedPricingParameter unifiedPricingParameter;
    Set productAttributes = new Set(Types::Class);
    Set customerAttributes = new Set(Types::Class);
    Set salesLineAttributes = new Set(Types::Class);
    Set salesTableAttributes = new Set(Types::Class);
    private static int64 TMP_REC_ID = -1;

}

Method.Source:
public void new(RecId _channelRecordId, RetailTransactionId _transactionId, RetailTempOrderItem _tempOrderItem = null, boolean _isTempOrderItemFilled = false)
{
    if (!RetailConfigurationParameters::getAllowPriceAdjustmentsToIncreasePrice())
    {
        RetailConfigurationParameters::createOrUpdateAllowPriceAdjustmentsToIncreasePrice(NoYes::Yes);
    }

    super(_channelRecordId, _transactionId, _tempOrderItem, _isTempOrderItemFilled);
    unifiedPricingParameter = new Microsoft.Dynamics.Commerce.Runtime.DataModel.UnifiedPricingParameter();
    unifiedPricingParameter.IsEnabled = true;
    unifiedPricingParameter.ShouldFindNextTradeAgreement = GUPParameters::find().PriceDiscSearchAgainDefault;
    this.initAttributesSetBySource();
}

/// <summary>
/// Collect values of pricing related properties described by <see cref="IPricingAttribute"/>.
/// The pricing object is a sales transaction.
/// </summary>
/// <param name="salesTransaction">The sales transaction.</param>
/// <param name="salesTransactionObject">The pricing object.</param>
public void CollectOrderPricingProperties(Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesTransaction salesTransaction,
    Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingAttributeSource salesTransactionObject)
{
    var dict = salesTransactionObject.PricingProperties;
    SalesTable pricingObject;
    select firstonly pricingObject where pricingObject.SalesId == mTransactionId;
    SetEnumerator enum = salesTableAttributes.getEnumerator();
    while (enum.moveNext())
    {
        GUPIPricingAttribute attribute = enum.current();
        GUPRetailPricingAttributeAdaptor retailPricingAttribute = new GUPRetailPricingAttributeAdaptor(attribute);
        anytype val = attribute.getValueOfAttribute(pricingObject);
        dict.Add(retailPricingAttribute, val);
    }
}

/// <summary>
/// Collect values of pricing related properties described by <see cref="IPricingAttribute"/>.
/// The pricing object is a sales line.
/// </summary>
/// <param name="salesLine">The sales line.</param>
/// <param name="salesLineObject">The pricing object.</param>
public void CollectOrderLinePricingProperties(Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesLine salesLine,
    Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingAttributeSource salesLineObject)
{
    var dict = salesLineObject.PricingProperties;
    SalesLine pricingObject;
    select firstonly pricingObject where pricingObject.InventTransId == salesLine.LineId;
    SetEnumerator enum = salesLineAttributes.getEnumerator();
    while (enum.moveNext())
    {
        GUPIPricingAttribute attribute = enum.current();
        GUPRetailPricingAttributeAdaptor retailPricingAttribute = new GUPRetailPricingAttributeAdaptor(attribute);
        anytype val = attribute.getValueOfAttribute(pricingObject);
        dict.Add(retailPricingAttribute, val);
    }
}

/// <summary>
/// Collect values of pricing related properties described by <see cref="IPricingAttribute"/>.
/// The pricing object is an item.
/// </summary>
/// <param name="itemId">The item identifier.</param>
/// <param name="itemObject">The pricing object.</param>
public void CollectItemPricingProperties(System.String itemId, Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingAttributeSource itemObject)
{
    Microsoft.Dynamics.Commerce.Runtime.DataModel.Item item = new Microsoft.Dynamics.Commerce.Runtime.DataModel.Item();
    item.ItemId = itemId;
    var dict = itemObject.PricingProperties;
    SalesLine pricingObject;
    pricingObject.ItemId = itemId;
    pricingObject.RecId = TMP_REC_ID;
    SetEnumerator enum = productAttributes.getEnumerator();
    while (enum.moveNext())
    {
        GUPIPricingAttribute attribute = enum.current();
        GUPRetailPricingAttributeAdaptor retailPricingAttribute = GUPRetailPricingDataManager::convertToClrPricingAttribute(attribute);

        anytype val = attribute.getValueOfAttribute(pricingObject);
        dict.Add(retailPricingAttribute, val);
    }
}

/// <summary>
/// Collect values of pricing related properties described by <see cref="IPricingAttribute"/>.
/// The pricing object is a customer.
/// </summary>
/// <param name="customerAccount">The customer account number.</param>
/// <param name="customerObject">The pricing object.</param>
public void CollectCustomerPricingProperties(System.String customerAccount, Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingAttributeSource customerObject)
{
    Microsoft.Dynamics.Commerce.Runtime.DataModel.Customer customer = new Microsoft.Dynamics.Commerce.Runtime.DataModel.Customer();
    customer.AccountNumber = customerAccount;
    var dict = customerObject.PricingProperties;
    SalesTable pricingObject;
    pricingObject.CustAccount = customerAccount;
    pricingObject.RecId = TMP_REC_ID;
    SetEnumerator enum = customerAttributes.getEnumerator();
    while (enum.moveNext())
    {
        GUPIPricingAttribute attribute = enum.current();
        GUPRetailPricingAttributeAdaptor retailPricingAttribute = new GUPRetailPricingAttributeAdaptor(attribute);
        anytype val = attribute.getValueOfAttribute(pricingObject);
        dict.Add(retailPricingAttribute, val);
    }
}

/// <summary>
/// Gets the value of global unified pricing parameter.
/// </summary>
/// <returns>The global unified pricing parameter.</returns>
public Microsoft.Dynamics.Commerce.Runtime.DataModel.UnifiedPricingParameter GetGlobalUnifiedPricingParameter()
{
    return unifiedPricingParameter;
}

/// <summary>
/// Gets the inventory dimension values.
/// </summary>
/// <param name="inventDimIds">The inventory dimension identifiers.</param>
/// <returns>Collection of <see cref="InventoryDimension"/>.</returns>
public System.Object ReadInventoryDimensions(System.Object inventDimIds)
{
    CLRObject crtInventDimIdList = inventDimIds;
    CLRObject clrEn = crtInventDimIdList.GetEnumerator();
    CLRObject crtInventoryDimensionList = this.createCLRList(new Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingMatchingDimension());

    while (clrEn.MoveNext())
    {
        System.String inventDimId = clrEn.get_Current();

        InventDim inventdim;

        if (inventDimId == '')
        {
            inventDim = InventDim::findOrCreateBlank();
        }
        else
        {
            select firstonly inventdim where inventdim.inventDimId == inventDimId;
        }

        Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingMatchingDimension inventoryDimension = new Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingMatchingDimension();
        if (inventdim)
        {
            inventoryDimension.ConfigId = inventdim.configId;
            inventoryDimension.ColorId = inventdim.InventColorId;
            inventoryDimension.StyleId = inventdim.InventStyleId;
            inventoryDimension.SizeId = inventdim.InventSizeId;
            inventoryDimension.SiteId = inventdim.InventSiteId;
            inventoryDimension.WarehouseId = inventdim.InventLocationId;
            inventoryDimension.DimensionId = inventDimId;
            crtInventoryDimensionList.Add(inventoryDimension);
        }
    }

    return crtInventoryDimensionList.AsReadOnly();
}

/// <summary>
/// Gets the unit of measure conversion values.
/// </summary>
/// <param name="itemId">The item identifier of the unit of measure conversions.</param>
/// <param name="fromUnitOfMeasureSymbol">The unit of measure to convert from.</param>
/// <param name="toUnitOfMeasureSymbols">The unit of measure list to convert to.</param>
/// <param name="productVariantRecordId">If item is distinct product variant, the product variant record identifier;
/// otherwise, 0L.</param>
/// <returns>The <see cref="UnitOfMeasureConversion"/>.</returns>
public System.Object ReadUnitOfMeasureConversions(
    System.String itemId,
    System.String fromUnitOfMeasureSymbol,
    System.Object toUnitOfMeasureSymbols,
    int64 productVariantRecordId)
{
    CLRObject crtUnitOfMeasureConversionList = this.createCLRList(new Microsoft.Dynamics.Commerce.Runtime.Services.PricingEngine.AxUnitOfMeasureConversion());

    UnitOfMeasure fromUnit = UnitOfMeasure::findBySymbol(fromUnitOfMeasureSymbol);
    RefRecId productId = InventTable::find(itemId).Product;

    CLRObject crtToUnitIdList = toUnitOfMeasureSymbols;
    CLRObject clrToUnitIdEn = crtToUnitIdList.GetEnumerator();
    while (clrToUnitIdEn.MoveNext())
    {
        System.String toUnitOfMeasureSymbol = clrToUnitIdEn.get_Current();
        UnitOfMeasure toUnit = UnitOfMeasure::findBySymbol(toUnitOfMeasureSymbol);
        if (!toUnit)
        {
            continue;
        }

        UnitOfMeasureConverter converter = UnitOfMeasureConverter::newFromConversionParameters(fromUnit.RecId, toUnit.RecId, NoYes::No, productId, NoYes::No);

        // If it is a variant and conversion is not available for variant then find the conversion for it's master product.
        if ( !converter.canValueBeConverted() && productVariantRecordId)
        {
            productId = productVariantRecordId;
            converter = UnitOfMeasureConverter::newFromConversionParameters(fromUnit.RecId, toUnit.RecId, NoYes::No, productId, NoYes::No);
        }

        if (converter.canValueBeConverted())
        {
            UnitOfMeasureConversionCache conversionCache = converter.cachedConversion();

            Microsoft.Dynamics.Commerce.Runtime.Services.PricingEngine.AxUnitOfMeasureConversion unitOfMeasureConversion = new Microsoft.Dynamics.Commerce.Runtime.Services.PricingEngine.AxUnitOfMeasureConversion();

            unitOfMeasureConversion.ItemId = itemId;
            unitOfMeasureConversion.FromUnitOfMeasureSymbol = fromUnitOfMeasureSymbol;
            unitOfMeasureConversion.ToUnitOfMeasureSymbol = toUnitOfMeasureSymbol;
            unitOfMeasureConversion.ProductRecordId = productId;

            unitOfMeasureConversion.Factor = conversionCache.Factor;
            unitOfMeasureConversion.FactorDenominator = conversionCache.FactorDenominator;
            unitOfMeasureConversion.Numerator = conversionCache.Numerator;
            unitOfMeasureConversion.Denominator = conversionCache.Denominator;
            unitOfMeasureConversion.InnerOffset = conversionCache.InnerOffset;
            unitOfMeasureConversion.OuterOffset = conversionCache.OuterOffset;

            switch (conversionCache.Rounding)
            {
                case UnitOfMeasureConversionRounding::Down:
                    unitOfMeasureConversion.RoundingMethod = Microsoft.Dynamics.Commerce.Runtime.DataModel.RoundingMethod::Down;
                    break;
                case UnitOfMeasureConversionRounding::Nearest:
                    unitOfMeasureConversion.RoundingMethod = Microsoft.Dynamics.Commerce.Runtime.DataModel.RoundingMethod::Nearest;
                    break;
                case UnitOfMeasureConversionRounding::Up:
                    unitOfMeasureConversion.RoundingMethod = Microsoft.Dynamics.Commerce.Runtime.DataModel.RoundingMethod::Up;
                    break;
                default:
                    unitOfMeasureConversion.RoundingMethod = Microsoft.Dynamics.Commerce.Runtime.DataModel.RoundingMethod::None;
                    break;
            }

            crtUnitOfMeasureConversionList.Add(unitOfMeasureConversion);
        }
        else
        {
            warning(strFmt("@SYS50546", fromUnit.Symbol, toUnit.Symbol));
        }
    }
    return crtUnitOfMeasureConversionList;
}

/// <summary>
/// Fetches the base price.
/// </summary>
/// <param name="itemIds">The item Ids.</param>
/// <param name="dateTime">The system date time.</param>
/// <param name="settings">The query result settings.</param>
/// <returns>Collection of base prices which maybe be appiled t o the given items.</returns>
public System.Object ReadGlobalUnifiedPricingItemBasePrice(
            System.Object itemIds,
            System.DateTimeOffset dateTime,
            Microsoft.Dynamics.Commerce.Runtime.DataModel.QueryResultSettings settings)
{
    CLRObject crtItemIdList = itemIds;
    CLRObject clrEn = crtItemIdList.GetEnumerator();
    var itemIdSet = new Set(Types::String);
    while (clrEn.MoveNext())
    {
        itemIdSet.add(clrEn.get_Current());
    }

    CLRObject crtBasePriceLineList = this.createCLRList(new Microsoft.Dynamics.Commerce.Runtime.DataModel.ItemBasePrice());

    date currentDate = this.GetDateInChannelTimeZone(dateTime);

    GUPItemBasePrice gupItemBasePrice;
    InventDim inventDim;

    GUPBasePriceType priceType = this.getBasePriceType();

    while select gupItemBasePrice
        order by gupItemBasePrice.ActivationDate desc, gupItemBasePrice.ModifiedDateTime desc
        where gupItemBasePrice.PriceType == priceType
            && (gupItemBasePrice.FromDate <= currentDate || gupItemBasePrice.FromDate <= noDate)
            && (gupItemBasePrice.ToDate >= currentDate || gupItemBasePrice.ToDate <= noDate)
        outer join inventDim
            where inventDim.inventDimId == gupItemBasePrice.InventDimId
    {
        if (itemIdSet.in(gupItemBasePrice.ItemId))
        {
            crtBasePriceLineList.Add(this.ConvertToItemBasePrice(gupItemBasePrice, inventDim));
        }
    }

    return crtBasePriceLineList.AsReadOnly();
}

/// <summary>
/// Fetch the superset of trade agreements which could apply to all of these items and customer for the given date.
/// </summary>
/// <param name="itemIds">The item Ids to fetch for agreements for.</param>
/// <param name="customerAccount">Optional. Customer account number to search by.</param>
/// <param name="minActiveDate">The earliest inclusive active date to search by. Must be less than or equal to maxActiveDate.</param>
/// <param name="maxActiveDate">The latest inclusive active date to search by. Must be greater than or equal to minActiveDate.</param>
/// <param name="currencyCode">Currency code to filter by.</param>
/// <param name="settings">The query result settings.</param>
/// <returns>Collection of trade agreements which may be applied to the given items.</returns>
public System.Object ReadGlobalUnifiedPricingTradeAgreements(
            System.Object itemIds,
            System.String customerAccount,
            System.DateTimeOffset minActiveDate,
            System.DateTimeOffset maxActiveDate,
            System.String currencyCode,
            Microsoft.Dynamics.Commerce.Runtime.DataModel.QueryResultSettings settings)
{
    PriceDiscTable              priceDiscTable;
    PriceDiscAdmTable           priceDiscAdmTable;
    PriceDiscAdmTrans           priceDiscAdmTrans;
    PriceDiscAdmName            priceDiscAdmName;
    InventDim                   inventDim;
    GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;

    ValidFromDate minToDate =  this.GetDateInChannelTimeZone(minActiveDate);
    ValidFromDate maxFromDate   =  this.GetDateInChannelTimeZone(maxActiveDate);

    CLRObject tradeAgreementList = this.createCLRList(new Microsoft.Dynamics.Commerce.Runtime.DataModel.TradeAgreement());
    Microsoft.Dynamics.Commerce.Runtime.DataModel.TradeAgreement tradeAgreement = new Microsoft.Dynamics.Commerce.Runtime.DataModel.TradeAgreement();
    boolean shouldUseGUPTradeAgreement = this.isTAFoundInPriceTree();

    // Find GUP trade agreement if: 1. Price tree is not enabled 2. Price tree is enabled, and TA component code is found in the tree.
    if (!GUPParameters::find().EnablePriceTree || shouldUseGUPTradeAgreement)
    {
        while select priceDiscTable
        where ((priceDiscTable.FromDate <= maxFromDate || priceDiscTable.FromDate <= noDate) &&
               (priceDiscTable.ToDate >= minToDate || priceDiscTable.ToDate <= noDate))
        join RecId, Priority from groupCombination
            where groupCombination.RecId == priceDiscTable.PriceComponentCombination
        join JournalNum, RecId from priceDiscAdmTrans where priceDiscAdmTrans.RecId == priceDiscTable.OriginalPriceDiscAdmTransRecId
        join JournalNum, JournalName from priceDiscAdmTable where priceDiscAdmTable.JournalNum == priceDiscAdmTrans.JournalNum
        join JournalName, PriceDiscPriceAttributeEnable from priceDiscAdmName
            where priceDiscAdmName.JournalName == priceDiscAdmTable.JournalName && priceDiscAdmName.PriceDiscPriceAttributeEnable == NoYes::Yes
        outer join inventDim
            where inventDim.inventDimId == priceDiscTable.InventDimId
        {
            tradeAgreement = this.ConvertToTradeAgreement(priceDiscTable, inventDim);
            tradeAgreement.CanApplyWithUnitConversion = priceDiscTable.UnitAppliesToAll;
            tradeAgreement.CanApplyPriceAdjustments = priceDiscTable.PriceApplyAdjustment;

            tradeAgreement.Dimension = GUPRetailPricingDataManager::ConvertToCrtInventoryDimension(inventDim);

            this.setCrtPricingRuleAndPriorityForTA(
            tradeAgreement, groupCombination.Priority,
            priceDiscTable.PricingRuleHeader, priceDiscTable.PricingRuleLine);

            tradeAgreementList.Add(tradeAgreement);
        }
    }

    return tradeAgreementList.AsReadOnly();
}

/// <summary>
/// Fetch the superset of trade adjustments which could apply to all of these items and customer for the given date.
/// </summary>
/// <param name="itemIds">The item Ids to fetch for adjustments for.</param>
/// <param name="minActiveDate">The earliest inclusive active date to search by. Must be less than or equal to maxActiveDate.</param>
/// <param name="maxActiveDate">The latest inclusive active date to search by. Must be greater than or equal to minActiveDate.</param>
/// <param name="currencyCode">Currency code to filter by.</param>
/// <param name="settings">The query result settings.</param>
/// <returns>Collection of trade adjustments which may be applied to the given items.</returns>
public System.Object ReadGlobalUnifiedPricingAdjustments(
            System.Object itemIds,
            System.DateTimeOffset minActiveDate,
            System.DateTimeOffset maxActiveDate,
            System.String currencyCode,
            Microsoft.Dynamics.Commerce.Runtime.DataModel.QueryResultSettings settings)
{
    ValidFromDate minToDate = this.GetDateInChannelTimeZone(minActiveDate);
    ValidToDate maxFromDate = this.GetDateInChannelTimeZone(maxActiveDate);

    CLRObject adjustmentList = this.createCLRList(new Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceAdjustment());

    RetailPeriodicDiscount promo;
    select firstonly RecId from promo
        where promo.PeriodicDiscountType == RetailDiscountOfferTypeBase::Promotion
               && promo.Status == RetailDisabledEnabled::Enabled
               && promo.IsGupDiscount == NoYes::Yes
               && promo.PriceComponentType == GUPPriceComponent::PriceMarginComponentAdjustment
               && ((promo.ValidFrom <= maxFromDate || promo.ValidFrom <= noDate)
               && (promo.ValidTo >= minToDate || promo.ValidTo <= noDate));
    if (!promo)
    {
        return adjustmentList.AsReadOnly();
    }

    Map validationPeriodLookup = new Map(Types::String, Types::AnyType);
    this.readRetailPriceAdjustments(adjustmentList, minToDate, maxFromDate, validationPeriodLookup);
    return adjustmentList.AsReadOnly();
}

/// <summary>
/// Fetch all retail discounts for the given items, striped by item Id and dimension Id.
/// </summary>
/// <param name="items">The set of items to search by. Set of pairs of item Id and variant dimension Id. Ignores the unit.</param>
/// <param name="minActiveDate">The earliest inclusive active date to search by. Must be less than or equal to maxActiveDate.</param>
/// <param name="maxActiveDate">The latest inclusive active date to search by. Must be greater than or equal to minActiveDate.</param>
/// <param name="currencyCode">Currency code to filter by.</param>
/// <param name="settings">The query result settings.</param>
/// <returns>The first value is a collection of price adjustments striped by item Id and variant dimension Id (if any), the second value represents all the validation periods used by the discovered price adjustments..</returns>
public System.Object ReadGlobalUnifiedPricingDiscounts(
           System.Object items,
           System.DateTimeOffset minActiveDate,
           System.DateTimeOffset maxActiveDate,
           System.String currencyCode,
           Microsoft.Dynamics.Commerce.Runtime.DataModel.QueryResultSettings settings)
{
    ValidFromDate minFromDate =  this.GetDateInChannelTimeZone(minActiveDate);
    ValidFromDate maxToDate =  this.GetDateInChannelTimeZone(maxActiveDate);

    CLRObject discountList = this.createCLRList(new Microsoft.Dynamics.Commerce.Runtime.DataModel.PeriodicDiscount());

    RetailPeriodicDiscount promo;
    select firstonly RecId from promo
        where  promo.Status == RetailDisabledEnabled::Enabled
               && promo.IsGupDiscount == NoYes::Yes
               && promo.PriceComponentType == GUPPriceComponent::RetailDiscounts
               && promo.PeriodicDiscountType != RetailDiscountOfferTypeBase::Promotion
               && promo.PeriodicDiscountType != RetailDiscountOfferTypeBase::Shipping
               && promo.PeriodicDiscountType != RetailDiscountOfferTypeBase::FreeItem
               && ((promo.ValidFrom <= minFromDate || promo.ValidFrom <= noDate)
               && (promo.ValidTo >= maxToDate || promo.ValidTo <= noDate));
    if (!promo)
    {
        return discountList.AsReadOnly();
    }

    Map validationPeriodLookup = new Map(Types::String, Types::AnyType);
    this.readRetailPeriodicDiscounts(discountList, minFromDate, maxToDate, validationPeriodLookup);
    return discountList.AsReadOnly();
}

private void initAttributesSetBySource()
{
    List pricingAttributes = GUPPricingAttributeRepository::getAllPricingAttributes();
    ListEnumerator enum = pricingAttributes.getEnumerator();
    while (enum.moveNext())
    {
        GUPAbstractPricingAttribute attribute = enum.current();
        GUPPricingAttributeSource source = GUPPricingAttributeRepository::getPricingAttributeAttributeAsObject(
            attribute,
            attributeStr(GUPPricingAttributeSourceDiscoveryAttribute)).parmSource();
        switch (source)
        {
            case GUPPricingAttributeSource::Product:
                productAttributes.add(attribute);
                break;
            case GUPPricingAttributeSource::Customer:
                customerAttributes.add(attribute);
                break;
            case GUPPricingAttributeSource::SalesLine:
                salesLineAttributes.add(attribute);
                break;
            case GUPPricingAttributeSource::SalesTable:
                salesTableAttributes.add(attribute);
                break;
        }
    }
}

private void readRetailPriceAdjustments(
    CLRObject _priceDataList,
    ValidFromDate _minToDate,
    ValidFromDate _maxFromDate,
    Map _validationPeriodLookup)
{
    RetailDiscountOffer periodicDiscount;
    RetailPeriodicDiscountLine periodicDiscountLine;
    UnitOfMeasure unitOfMeasure;
    InventDim inventDim;
    GUPTierPriceAdjustmentLine tierPriceAdjustmentLine;

    GUPPriceComponentCodeSetup marginComponentSetup;
    GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;

    Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceAdjustment crtPriceAdjustment;

    // Lookup of promotion discount offer Ids to determine whether the offer Id has already been added to RetailTempOrderData.
    Set promoOfferIdSet = new Set(Types::String);

    delete_from mTmpOrderData;

    RecId gupPriceTreeRecId = GUPPricingTree::find(this.unifiedPricingParameter.PriceTreeName).RecId;

    while select marginComponentSetup
        order by marginComponentSetup.CalculationSequence
        join periodicDiscount
        where marginComponentSetup.PriceComponentCodeName == periodicDiscount.PriceComponentCodeName &&
              marginComponentSetup.PricingTree == gupPriceTreeRecId &&
              periodicDiscount.Status == RetailDisabledEnabled::Enabled &&
              periodicDiscount.IsGupDiscount == NoYes::Yes &&
              periodicDiscount.PriceComponentType == GUPPriceComponent::PriceMarginComponentAdjustment &&
              periodicDiscount.PeriodicDiscountType == RetailDiscountOfferTypeBase::Promotion &&
             ((periodicDiscount.ValidFrom <= _maxFromDate || periodicDiscount.ValidFrom <= noDate) &&
              (periodicDiscount.ValidTo >= _minToDate || periodicDiscount.ValidTo <= noDate))
        join periodicDiscountLine
            where periodicDiscount.OfferId == periodicDiscountLine.OfferId
        join RecId, Priority from groupCombination
            where groupCombination.RecId == periodicDiscountLine.PriceAttributeGroupCombinationRecId
        outer join tierPriceAdjustmentLine
            where tierPriceAdjustmentLine.OfferId == periodicDiscount.OfferId
        outer join inventDim
            where inventDim.inventDimId == periodicDiscountLine.InventDimId
        outer join RecId, Symbol from unitOfMeasure
            where unitOfMeasure.RecId == periodicDiscountLine.UnitOfMeasure
    {
        crtPriceAdjustment = this.ConvertToPriceAdjustmentV2(periodicDiscount, periodicDiscountLine, '', periodicDiscountLine.InventDimId, unitOfMeasure);
        if (periodicDiscount.IsTierConfigurationEnabled == NoYes::Yes)
        {
            if (periodicDiscount.TierPriceAdjustmentMethod == GUPPriceTermCalculateMethod::Percent)
            {
                crtPriceAdjustment.DiscountMethod = enum2int(RetailDiscountOfferLineDiscMethodBase::PercentOff);
            }
            else
            {
                crtPriceAdjustment.DiscountMethod = enum2int(RetailDiscountOfferLineDiscMethodBase::AmountOff);
            }
            while select tierPriceAdjustmentLine
                where tierPriceAdjustmentLine.OfferId == periodicDiscount.OfferId
            {
                this.addCrtPriceAdjustmentTierForPriceAdjustment(crtPriceAdjustment, tierPriceAdjustmentLine);
            }
        }
        crtPriceAdjustment.DiscountAmount = (-crtPriceAdjustment.DiscountAmount);
        crtPriceAdjustment.DiscountPercent = (-crtPriceAdjustment.DiscountPercent);
        crtPriceAdjustment.CanCompoundOnAdjustedPrice = marginComponentSetup.CompoundcalculationBasis;
        crtPriceAdjustment.CanApplyWithUnitConversion = periodicDiscountLine.UnitAppliesToAll;

        crtPriceAdjustment.ValidationPeriod = this.setCrtValidationPeriod(periodicDiscount, _validationPeriodLookup);
        crtPriceAdjustment.Dimension = GUPRetailPricingDataManager::ConvertToCrtInventoryDimension(inventDim);

        this.setCrtPricingRuleAndPriorityForPriceAdjustment(
            crtPriceAdjustment, groupCombination.Priority,
            periodicDiscount.HeaderPricingRule, periodicDiscountLine.LinePricingRule);

        _priceDataList.Add(crtPriceAdjustment);

        this.addOfferIdToTmpOrderDataList(periodicDiscount.OfferId, promoOfferIdSet);
    }

    tmpOrderDataInsertList.insertDatabase();
}

private void readRetailPeriodicDiscounts(
    CLRObject _priceDataList,
    ValidFromDate _minFromDate,
    ValidFromDate _maxToDate,
    Map _validationPeriodLookup)
{
    GUPPriceComponentCode priceComponentCode;
    GUPPriceComponentCodeSetup priceComponentCodeSetup;
    RetailPeriodicDiscount periodicDiscount;
    RetailPeriodicDiscountLine periodicDiscountLine;
    UnitOfMeasure unitOfMeasure;
    InventDim inventDim;

    GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;

    int discountType = 0;

    Microsoft.Dynamics.Commerce.Runtime.DataModel.PeriodicDiscount crtDiscount;
    Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingComponentCode crtPricingComponentCode;

    delete_from mTmpOrderData;

    RecId gupPriceTreeRecId = GUPPricingTree::find(this.unifiedPricingParameter.PriceTreeName).RecId;

    // Key = discount offer id, value = list of excluded price component code groups.
    Map discountExclusionMap = this.createDiscountExclusionMap(_minFromDate, _maxToDate);

    while select priceComponentCodeSetup
        join periodicDiscount
        where priceComponentCodeSetup.PriceComponentCodeName == periodicDiscount.PriceComponentCodeName
           && priceComponentCodeSetup.PricingTree == gupPriceTreeRecId
           && periodicDiscount.Status == RetailDisabledEnabled::Enabled
           && periodicDiscount.IsGupDiscount == NoYes::Yes
           && periodicDiscount.PriceComponentType == GUPPriceComponent::RetailDiscounts
           && periodicDiscount.PeriodicDiscountType != RetailDiscountOfferTypeBase::Promotion 
           && periodicDiscount.PeriodicDiscountType != RetailDiscountOfferTypeBase::Shipping
           && periodicDiscount.PeriodicDiscountType != RetailDiscountOfferTypeBase::FreeItem
           && ((periodicDiscount.ValidFrom <= _minFromDate || periodicDiscount.ValidFrom <= noDate)
           && (periodicDiscount.ValidTo >= _maxToDate || periodicDiscount.ValidTo <= noDate))
        join priceComponentCode
            where priceComponentCodeSetup.PriceComponentCodeName == priceComponentCode.Name
        join periodicDiscountLine
            where periodicDiscount.OfferId == periodicDiscountLine.OfferId
        join RecId, Priority from groupCombination
            where groupCombination.RecId == periodicDiscountLine.PriceAttributeGroupCombinationRecId
        outer join inventDim
            where inventDim.inventDimId == periodicDiscountLine.InventDimId
        outer join RecId, Symbol from unitOfMeasure
            where unitOfMeasure.RecId == periodicDiscountLine.UnitOfMeasure
    {
        crtDiscount = this.ConvertToCrtPeriodicDiscountV2(periodicDiscount, periodicDiscountLine, unitOfMeasure, discountType, '', periodicDiscountLine.InventDimId);

        crtPricingComponentCode = this.ConvertToCrtPricingComponentCode(priceComponentCodeSetup, priceComponentCode);
        crtDiscount.PricingComponentCode = crtPricingComponentCode;
        crtDiscount.PricingPriorityNumber = 1000 - crtPricingComponentCode.CalculationSequence;

        this.fillDiscountExclusionSet(crtDiscount, periodicDiscount, discountExclusionMap);

        crtDiscount.ValidationPeriod = this.setCrtValidationPeriod(periodicDiscount, _validationPeriodLookup);
        crtDiscount.Dimension = GUPRetailPricingDataManager::ConvertToCrtInventoryDimension(inventDim);

        this.setCrtPricingRuleAndPriorityForDiscount(
            crtDiscount, groupCombination.Priority,
            periodicDiscount.HeaderPricingRule, periodicDiscountLine.LinePricingRule);

        _priceDataList.Add(crtDiscount);

        this.addOfferIdToTmpOrderDataList(periodicDiscount.OfferId, offerIdSet);
    }

    tmpOrderDataInsertList.insertDatabase();
}

/// <summary>
/// Put the excluded price component code groups into given discount record.
/// </summary>
/// <param name = "_crtDiscount">Discount data model (header).</param>
/// <param name = "_periodicDiscount">Discount record in dynamics AX.</param>
/// <param name = "_discountExclusionMap">Price component code group(s) excluded by given record.</param>
private void fillDiscountExclusionSet(Microsoft.Dynamics.Commerce.Runtime.DataModel.PeriodicDiscount _crtDiscount,
    RetailPeriodicDiscount _periodicDiscount, Map _discountExclusionMap)
{
    if (_discountExclusionMap.exists(_periodicDiscount.OfferId))
    {
        List exclusionList = _discountExclusionMap.lookup(_periodicDiscount.OfferId);
        ListEnumerator listEnum = exclusionList.getEnumerator();
        var groupExclusionSet = _crtDiscount.DiscountGroupExclusionSet;

        while (listEnum.moveNext())
        {
            groupExclusionSet.Add(listEnum.current());
        }
    }
}

/// <summary>
/// Create a map with key = discount offer id, and value = list of excluded price comonent code groups.
/// </summary>
/// <returns>The required map.</returns>
private Map createDiscountExclusionMap(ValidFromDate _minFromDate, ValidFromDate _maxToDate)
{
    GUPDiscountPriceComponentGroupExclusionList discountPriceComponentGroupExclusionList;
    GUPPriceComponentCodeSetup priceComponentCodeSetup;
    RetailPeriodicDiscount periodicDiscount;

    Map exclusionListMap = new Map(Types::String, Types::AnyType);
    while select priceComponentCodeSetup
        join periodicDiscount
            where priceComponentCodeSetup.PriceComponentCodeName == periodicDiscount.PriceComponentCodeName
            //&& priceComponentCodeSetup.PricingTree == gupPriceTreeRecId
                && periodicDiscount.Status == RetailDisabledEnabled::Enabled
                && periodicDiscount.IsGupDiscount == NoYes::Yes
                && periodicDiscount.PeriodicDiscountType != RetailDiscountOfferTypeBase::Promotion && periodicDiscount.PeriodicDiscountType != RetailDiscountOfferTypeBase::Shipping
                && ((periodicDiscount.ValidFrom <= _minFromDate || periodicDiscount.ValidFrom <= noDate)
                && (periodicDiscount.ValidTo >= _maxToDate || periodicDiscount.ValidTo <= noDate))
        join discountPriceComponentGroupExclusionList
            where discountPriceComponentGroupExclusionList.OfferId == periodicDiscount.OfferId
                && discountPriceComponentGroupExclusionList.IsExcluded == NoYes::Yes
        // order by periodicDiscount.OfferId
    {
        if (!exclusionListMap.exists(periodicDiscount.OfferId))
        {
            exclusionListMap.add(periodicDiscount.OfferId, new List(Types::String));
        }
        List exclusionList = exclusionListMap.lookup(periodicDiscount.OfferId);
        exclusionList.addEnd(discountPriceComponentGroupExclusionList.PriceComponentCodeGroup);
    }

    return exclusionListMap;
}

[Hookable(true)]
protected Microsoft.Dynamics.Commerce.Runtime.DataModel.PeriodicDiscount ConvertToCrtPeriodicDiscountV2(
    RetailPeriodicDiscount periodicDiscount,
    RetailPeriodicDiscountLine periodicDiscountLine,
    UnitOfMeasure unitOfMeasure,
    int discountType,
    ItemId itemId,
    InventDimId inventDimId)
{
    Microsoft.Dynamics.Commerce.Runtime.DataModel.PeriodicDiscount crtDiscount = super(periodicDiscount, periodicDiscountLine, unitOfMeasure, discountType, itemId, inventDimId);

    crtDiscount.IsMandatory = periodicDiscountLine.IsMandatory;
    crtDiscount.AmountThreshold = periodicDiscountLine.LeastAmount;

    return crtDiscount;
}

protected Microsoft.Dynamics.Commerce.Runtime.DataModel.ValidationPeriod setCrtValidationPeriod(
    RetailPeriodicDiscount _periodicDiscount,
    Map _validationPeriodLookup)
{
    Microsoft.Dynamics.Commerce.Runtime.DataModel.ValidationPeriod crtValidationPeriod = null;

    if (_periodicDiscount.ValidationPeriodId)
    {
        if (_validationPeriodLookup.exists(_periodicDiscount.ValidationPeriodId))
        {
            crtValidationPeriod = _validationPeriodLookup.lookup(_periodicDiscount.ValidationPeriodId);
        }
        else
        {
            crtValidationPeriod = this.GetValidationPeriod(_periodicDiscount.ValidationPeriodId);
            _validationPeriodLookup.insert(_periodicDiscount.ValidationPeriodId, crtValidationPeriod);
        }
    }

    return crtValidationPeriod;
}

