public static Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingMatchingRule ConvertToCrtPricingRule(
    RefRecId _pricingRuleRecId)
{
    Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingMatchingRule crtPricingRule = new Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingMatchingRule();
    CLRObject ruleExclusions = crtPricingRule.RuleExclusions;

    if (_pricingRuleRecId)
    {
        GUPPricingRule localPricingRule = GUPPricingRule::find(_pricingRuleRecId);
        GUPPricingAttributeGroup priceAttributeGroup = GUPPricingAttributeGroup::findByName(localPricingRule.PriceAttributeGroupName);

        crtPricingRule.Id = any2Str(_pricingRuleRecId);
        crtPricingRule.ExclusionType = localPricingRule.ExclusionType;
        crtPricingRule.SourceLevel = localPricingRule.getSourceLevel();
        crtPricingRule.PricingAttributeGroupId = any2Str(priceAttributeGroup.RecId);

        GUPPricingAttributeLink pricingAttributeLink;
        GUPPricingRuleCondition pricingRuleCondition;
        GUPPricingRuleExclusion pricingRuleExclusion;

        while select pricingAttributeLink
            where pricingAttributeLink.PriceAttributeGroupName == priceAttributeGroup.Name
            outer join pricingRuleCondition
                where pricingRuleCondition.RuleId == localPricingRule.RecId && pricingRuleCondition.ConditionAttribute == pricingAttributeLink.RecId
            outer join pricingRuleExclusion
                where pricingRuleExclusion.RuleId == localPricingRule.RecId
        {
            if (pricingRuleExclusion.RecId)
            {
                ruleExclusions.Add(pricingRuleExclusion.Exclusion);
            }

            if (pricingRuleCondition.RecId)
            {
                GUPPriceEngineConditionValueObject originConditionValueObject = new GUPPriceEngineConditionValueObject(pricingRuleCondition.ConditionValue, pricingAttributeLink);
                GUPIPricingAttribute originAttribute = originConditionValueObject.parmPricingAttribute();

                if (pricingAttributeLink.AttributeName == "@GlobalUnifiedPricing:GUPPricingAttributeCustomerPriceGroupName" || pricingAttributeLink.AttributeName == "@GlobalUnifiedPricing:GUPPricingAttributeProductPriceGroupName")
                {
                    str conditionGrpName = pricingRuleCondition.ConditionValue;
                    GUPPricingAttributeLink actualAttributeLink;

                    while select actualAttributeLink where actualAttributeLink.PriceAttributeGroupName == conditionGrpName
                    {
                        GUPIPricingAttribute actualAttribute = actualAttributeLink.pricingAttribute();
                        GUPRetailPricingAttributeAdaptor actualAttributeAdaptor = GUPRetailPricingDataManager::convertToClrPricingAttribute(actualAttribute);
                        if (actualAttributeLink.DefaultValue != '')
                        {
                            crtPricingRule.AddCondition(actualAttributeAdaptor, pricingAttributeLink.Priority, actualAttributeLink.DefaultValue);
                        }
                    }
                }
                else
                {
                    GUPRetailPricingAttributeAdaptor retailPricingAttributeAdaptor = GUPRetailPricingDataManager::convertToClrPricingAttribute(originAttribute);
                    crtPricingRule.AddCondition(retailPricingAttributeAdaptor, pricingAttributeLink.Priority, pricingRuleCondition.ConditionValue);
                }
            }
        }
    }

    return crtPricingRule;
}

private static Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceAdjustmentTier ConvertToPriceAdjustmentTier(GUPTierPriceAdjustmentLine tierPriceAdjustmentLine)
{
    Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceAdjustmentTier crtTier = new Microsoft.Dynamics.Commerce.Runtime.DataModel.PriceAdjustmentTier();

    crtTier.QuantityThreshold = tierPriceAdjustmentLine.QtyLowest;
    crtTier.DiscountValue = -tierPriceAdjustmentLine.PriceDiscPct;

    return crtTier;
}

private Microsoft.Dynamics.Commerce.Runtime.DataModel.ItemBasePrice ConvertToItemBasePrice(GUPItemBasePrice gupItemBasePrice, InventDim inventDim)
{
    Microsoft.Dynamics.Commerce.Runtime.DataModel.ItemBasePrice crtItemBasePrice = new Microsoft.Dynamics.Commerce.Runtime.DataModel.ItemBasePrice();

    crtItemBasePrice.Id = int642Str(gupItemBasePrice.RecId);
    crtItemBasePrice.ItemId = gupItemBasePrice.ItemId;
    crtItemBasePrice.InventoryDimensionId = gupItemBasePrice.InventDimId;
    crtItemBasePrice.MarkupAmount = gupItemBasePrice.Markup;
    crtItemBasePrice.MarkupQuantity = gupItemBasePrice.MarkupQty;
    crtItemBasePrice.Price = gupItemBasePrice.Price;
    crtItemBasePrice.PriceUnit = gupItemBasePrice.PriceQty;
    crtItemBasePrice.IsMarkupIncluded = gupItemBasePrice.PriceAllocateMarkup;
    crtItemBasePrice.UnitOfMeasureSymbol = gupItemBasePrice.UnitId;
    crtItemBasePrice.FromDate = this.ConvertDateToSystemDateTimeOffset(gupItemBasePrice.FromDate);
    crtItemBasePrice.ToDate = this.ConvertDateToSystemDateTimeOffset(gupItemBasePrice.ToDate);
    crtItemBasePrice.ActivatedDate = this.ConvertDateToSystemDateTimeOffset(gupItemBasePrice.ActivationDate);
    crtItemBasePrice.Dimension = GUPRetailPricingDataManager::ConvertToCrtInventoryDimension(inventDim);

    return crtItemBasePrice;
}

protected Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingComponentCode ConvertToCrtPricingComponentCode(
    GUPPriceComponentCodeSetup _priceComponentCodeSetup,
    GUPPriceComponentCode _priceComponentCode)
{
    Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingComponentCode crtPricingComponentCode = new Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingComponentCode();

    crtPricingComponentCode.PricingComponentCodeName = _priceComponentCodeSetup.PriceComponentCodeName;
    crtPricingComponentCode.CalculationSequence = _priceComponentCodeSetup.CalculationSequence;
    crtPricingComponentCode.CanCompoundOnAdjustedPrice = _priceComponentCodeSetup.CompoundCalculationBasis;
    crtPricingComponentCode.PricingComponentCodeConcurrencyMode = _priceComponentCodeSetup.ConcurrencyModeAcrossPriority;
    crtPricingComponentCode.PriceComponentCodeGroup = _priceComponentCode.PriceComponentCodeGroup;

    return crtPricingComponentCode;
}

public static Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingMatchingDimension ConvertToCrtInventoryDimension(InventDim inventDim)
{
    const str Blank = 'AllBlank';
    Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingMatchingDimension inventoryDimension = new Microsoft.Dynamics.Commerce.Runtime.DataModel.PricingMatchingDimension();

    inventoryDimension.ConfigId = inventdim.configId;
    inventoryDimension.ColorId = inventdim.InventColorId;
    inventoryDimension.StyleId = inventdim.InventStyleId;
    inventoryDimension.SizeId = inventdim.InventSizeId;
    inventoryDimension.SiteId = inventdim.InventSiteId;
    inventoryDimension.WarehouseId = inventdim.InventLocationId;
    inventoryDimension.DimensionId = inventDim.inventDimId != Blank ? inventDim.inventDimId : '';

    return inventoryDimension;
}

private GUPBasePriceType getBasePriceType()
{
    GUPPriceComponentCodeSetup priceComponentCodeSetup;
    RecId gupPriceTreeRecId = GUPPricingTree::find(this.unifiedPricingParameter.PriceTreeName).RecId;

    select firstonly PriceComponent, RecId from priceComponentCodeSetup
        where priceComponentCodeSetup.PricingTree == gupPriceTreeRecId &&
              (priceComponentCodeSetup.PriceComponent == GUPPriceComponent::BasePriceInventoryPrice ||
               priceComponentCodeSetup.PriceComponent == GUPPriceComponent::BasePricePurchasePrice ||
               priceComponentCodeSetup.PriceComponent == GUPPriceComponent::BasePriceSalesPrice);
    if (priceComponentCodeSetup.RecId)
    {
        return GUPItemBasePrice::getPriceTypeFromPriceComponent(priceComponentCodeSetup.PriceComponent);
    }
    else
    {
        return GUPParameters::find().ActivePrice_FallbackPriceBasis;
    }
}

private static GUPRetailPricingAttributeAdaptor convertToClrPricingAttribute(GUPIPricingAttribute attribute)
{
    GUPRetailPricingAttributeAdaptor retailPricingAttribute;

    if (classIdGet(attribute) == classNum(GUPPricingAttributeEcoResProductCategoryCategory))
    {
        retailPricingAttribute = new GUPProductCategoryPricingAttributeAdaptor();
    }
    else
    {
        retailPricingAttribute = new GUPRetailPricingAttributeAdaptor(attribute);
    }

    return retailPricingAttribute;
}

private boolean isTAFoundInPriceTree()
{
    GUPPriceComponentCodeSetup priceComponentCodeSetup;
    RecId gupPriceTreeRecId = GUPPricingTree::find(this.unifiedPricingParameter.PriceTreeName).RecId;

    select firstonly PriceComponent, RecId from priceComponentCodeSetup
        where priceComponentCodeSetup.PricingTree == gupPriceTreeRecId &&
              priceComponentCodeSetup.PriceComponent == GUPPriceComponent::SalesTradeAgreement;

    return priceComponentCodeSetup.RecId;
}
